// Obtiene la respuesta cruda del LLM
let rawText = $input.first().json.choices?.[0]?.message?.content || 
              $input.first().json.text || 
              $input.first().json.response || 
              "";

// Limpieza nivel 1: Elimina bloques de markdown
let cleanText = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

// Limpieza nivel 2: Elimina caracteres de control invisibles
cleanText = cleanText.replace(/[\u0000-\u001F\u007F-\u009F]/g, '');

// Limpieza nivel 3: Reemplaza comillas simples por dobles (solo si es necesario)
// Pero preserva las comillas dobles dentro de strings
try {
  const parsedJson = JSON.parse(cleanText);
  return [{ json: parsedJson }];
} catch (e) {
  // Intento 2: Si falla, trata de extraer el JSON de cualquier texto envolvente
  const jsonMatch = cleanText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      const extractedJson = JSON.parse(jsonMatch[0]);
      return [{ json: extractedJson }];
    } catch (e2) {
      // Intento 3: Si sigue fallando, construye un JSON de error estructurado
      return [{ json: { 
        error: "Formato JSON inválido tras múltiples intentos",
        raw_output: rawText.substring(0, 500) + (rawText.length > 500 ? "..." : ""),
        evaluacion: {
          margen_respetado: 0,
          calculos_correctos: false,
          reglas_credito_respetadas: 0,
          citas_fuentes_reales: false,
          score_total: 0
        },
        dictamen: "REVISION_HUMANA",
        razon_tecnica: "El LLM no devolvió un JSON válido. Se requiere revisión humana manual."
      }}];
    }
  }

  // Fallback total
  return [{ json: { 
    error: "No se encontró estructura JSON en la respuesta",
    raw_output: rawText.substring(0, 500),
    evaluacion: {
      margen_respetado: 0,
      calculos_correctos: false,
      reglas_credito_respetadas: 0,
      citas_fuentes_reales: false,
      score_total: 0
    },
    dictamen: "REVISION_HUMANA",
    razon_tecnica: "Respuesta del LLM no estructurada. Revisión manual requerida."
  }}];
}

const entrada = $input.first().json;
return [{
  json: {
    pedido_generado: entrada.pedido_generado || entrada,
    politicas_base: entrada.politicas_base || {
      productos: entrada.productos, regla_descuento: entrada.regla_descuento,
      plazo_pago_max: entrada.plazo_pago_max, fuentes_citadas: entrada.fuentes_citadas
    }
  }
}];

// Verifica si hubo error en el parsing anterior
const input = $input.first().json;

if (input.error) {
  return [{
    json: {
      evaluacion: {
        margen_respetado: 0,
        calculos_correctos: false,
        reglas_credito_respetadas: 0,
        citas_fuentes_reales: false,
        score_total: 0
      },
      dictamen: "REVISION_HUMANA",
      razon_tecnica: input.razon_tecnica || "Error de parsing en evaluación. Requiere revisión manual."
    }
  }];
}

// Recibe la evaluación del LLM
const evaluacion = input.evaluacion || {};
const dictamenOriginal = input.dictamen;
const razonTecnicaOriginal = input.razon_tecnica || "";

// ✅ CORRECCIÓN: Usar el score_total que ya calculó el LLM
// El LLM ya devolvió un score coherente (0-5), no hay que recalcularlo
const scoreTotal = Number(evaluacion.score_total) || 0;

// Validar que el score esté en rango 0-5
const scoreValidado = Math.max(0, Math.min(5, scoreTotal));

// El Juez decide basándose en el score del LLM
const dictamenFinal = scoreValidado >= 4 ? "APROBAR_AUTOMATICO" : "REVISION_HUMANA";

// Genera razón técnica coherente
let razonTecnicaFinal = "";

if (scoreValidado >= 4) {
  razonTecnicaFinal = `AUDITORÍA APROBADA (Score: ${scoreValidado.toFixed(2)}/5.0). `;
  razonTecnicaFinal += `Margen: ${evaluacion.margen_respetado}/1. Cálculos: ${evaluacion.calculos_correctos ? 'Correctos' : 'Incorrectos'}. `;
  razonTecnicaFinal += `Crédito: ${evaluacion.reglas_credito_respetadas}/1. Fuentes: ${evaluacion.citas_fuentes_reales ? 'Reales' : 'No reales'}. `;
  razonTecnicaFinal += `El pedido cumple políticas y puede procesarse automáticamente.`;
} else {
  razonTecnicaFinal = `AUDITORÍA RECHAZADA (Score: ${scoreValidado.toFixed(2)}/5.0). `;
  razonTecnicaFinal += `Margen: ${evaluacion.margen_respetado}/1. Cálculos: ${evaluacion.calculos_correctos ? 'Correctos' : 'Incorrectos'}. `;
  razonTecnicaFinal += `Crédito: ${evaluacion.reglas_credito_respetadas}/1. Fuentes: ${evaluacion.citas_fuentes_reales ? 'Reales' : 'No reales'}. `;
  razonTecnicaFinal += `No cumple umbral mínimo (4.0). Requiere revisión humana. `;

  if (Number(evaluacion.margen_respetado) === 0) razonTecnicaFinal += `Problema: margen no respetado. `;
  if (Number(evaluacion.reglas_credito_respetadas) === 0) razonTecnicaFinal += `Problema: crédito excedido. `;
  if (!evaluacion.calculos_correctos) razonTecnicaFinal += `Problema: cálculos incorrectos. `;
  if (!evaluacion.citas_fuentes_reales) razonTecnicaFinal += `Problema: fuentes no reales. `;
}

return [{
  json: {
    evaluacion: {
      margen_respetado: Number(evaluacion.margen_respetado) || 0,
      calculos_correctos: evaluacion.calculos_correctos || false,
      reglas_credito_respetadas: Number(evaluacion.reglas_credito_respetadas) || 0,
      citas_fuentes_reales: evaluacion.citas_fuentes_reales || false,
      score_total: scoreValidado
    },
    dictamen: dictamenFinal,
    razon_tecnica: razonTecnicaFinal
  }
}];
